input.metrics:
{
  "dimension_tables": ["d_calendar_week", "d_as_of"],
  "metrics": [
    {
      "id": "first_week_activation",
      "name": "First-week activation",
      "asks": ["Where do new members drop off in their first 7 days", "First-week funnel", "Share who join a board, connect and post within 7 days of signup"],
      "tables": ["d_member_first_week"],
      "definition": [
        ["Population", "Members at least 7 days past signup (signup week starts Monday)"],
        ["Steps", "Joined a board → shared a board with another member → first post → another member commented on or liked their post"],
        ["Window", "Every step within 7 days of signup, after the previous step"]
      ],
      "seed_panel": "activation_funnel"
    },
    {
      "id": "connected_retention",
      "name": "Retention by first-week connection",
      "asks": ["Do members who connect in their first week stay longer", "Weekly retention by connection"],
      "tables": ["d_member_first_week", "d_member_activity_week"],
      "definition": [
        ["Population", "Members who joined a board within 7 days of signup"],
        ["Groups", "Whether they shared a board with another member within 7 days"],
        ["Retention", "Wn = at least one post, comment or like in days [7n, 7n+7) after signup; only members whose window has fully passed count in the denominator"]
      ],
      "seed_panel": "connected_retention"
    },
    {
      "id": "member_retention",
      "name": "Weekly retention by signup week",
      "asks": ["How many weeks do new members stay active", "Signup cohort retention", "Retention by week"],
      "tables": ["d_member", "d_member_activity_week"],
      "definition": [
        ["Population", "Members who signed up on or after cohort_start"],
        ["Retention", "Wn = at least one post, comment or like in days [7n, 7n+7) after signup; only members whose window has fully passed count in the denominator"],
        ["Deleted accounts", "Members who left stay in the denominator"]
      ]
    },
    {
      "id": "weekly_activity",
      "name": "Weekly writing activity",
      "asks": ["How many posts, comments and likes are made each week", "Weekly active members"],
      "tables": ["d_activity", "d_member"],
      "definition": [
        ["Activity", "Posts, comments, replies and likes (deleted ones still count when they were made)"],
        ["Week", "Starts Monday"]
      ]
    }
  ]
}

